uro_onco = [
 {"cat":"Prostate","q":"What are the 3 well-established risk factors for prostate cancer?",
  "a": "<ul><li><b>Increasing age</b> — single most important demographic factor</li><li><b>Ethnic origin</b> — e.g., Japanese men have a low incidence</li><li><b>Heredity</b> — 1 first-line relative doubles risk; 2+ relatives → 5–11-fold increase</li></ul>PCa is the most common solid neoplasm in Europe and 2nd most common cause of cancer death in men."},
 {"cat":"Prostate","q":"What are the PSA and its derivatives in prostate cancer?",
  "a": "PSA is a glycoprotein (serine protease) produced by benign and malignant prostate tissue; normal ≤2.5–4 ng/mL by age. Derivatives: <b>free/total PSA ratio</b>; <b>PSA density</b> (PSA ÷ prostate volume; &gt;0.15 = high risk); PSA velocity."},
 {"cat":"Prostate","q":"How is prostate cancer diagnosed and staged?",
  "a": "Diagnosis: symptoms/signs (DRE — induration), PSA, <b>TRUS-guided biopsy</b> confirms histology, diagnostic TURP. Local staging (T): <b>MR imaging</b> + DCE-MRI in equivocal cases. Metastasis staging: <b>bone scan</b> for skeletal mets; PET/CT or whole-body MRI in equivocal cases; PLND for nodal spread."},
 {"cat":"Prostate","q":"Explain the Gleason score.",
  "a": "Grading of adenocarcinoma of the prostate (which is &gt;95% of prostate cancers) by low-power glandular architecture: patterns 1–5 (1 = well-formed closely packed glands → 5 = no glandular differentiation, sheets). <b>Score = sum of the two most common patterns; ranges 2–10</b> (2 least aggressive, 10 most aggressive)."},
 {"cat":"Prostate","q":"Describe the androgen axis and the two routes of androgen deprivation.",
  "a": "Hypothalamus → LHRH → pituitary LH/FSH → Leydig cells → testosterone → <b>5-α-reductase converts T to DHT (≈10× more powerful)</b>. Depriving prostate cells of androgen → apoptosis. <b>Routes:</b> (1) suppress testicular androgen secretion — surgical (bilateral orchiectomy) or medical castration (LHRH agonists/antagonists); (2) inhibit action of circulating androgens — <b>anti-androgens</b> (compete with T/DHT at receptor). Complete androgen blockade = castration + anti-androgen."},
 {"cat":"Prostate","q":"Summarize treatment of prostate cancer by stage (T1/T2).",
  "a": "<b>T1:</b> watchful waiting / active surveillance (standard for Gleason ≤6, ~10-year life expectancy), radical prostatectomy, or radiotherapy; hormonal therapy not an option. <b>T2:</b> <b>radical prostatectomy</b> (standard for 10-year survival), radiotherapy, brachytherapy (low-risk, small prostate); hormonal therapy only for palliation; combination for high-risk."},
 {"cat":"Bladder","q":"List the inducing agents (carcinogens) of bladder cancer.",
  "a": "Viruses; chemical carcinogens — <b>aniline dyes</b>; cigarette smoking (nitrosamines, 2-naphthylamine, 4-aminobiphenyl); coffee; analgesics (phenacetin); artificial sweeteners; bacterial/parasitic/fungal infections; bladder calculi; genotoxic chemotherapeutic agents. Bladder cancer is &gt;2.5× more common in men; 4th most common cancer in men."},
 {"cat":"Bladder","q":"What is the geographic variation of squamous cell carcinoma of the bladder?",
  "a": "SCC: 1% of bladder cancers in England, 3–7% in the USA, <b>40–75% in Egypt</b> — ~80% of Egyptian SCCs associated with chronic <b>Schistosoma haematobium</b> infection. Patients are 10–20 years younger than TCC patients; bilharzial cancers are exophytic/nodular, well-differentiated, with relatively low metastasis."},
 {"cat":"Bladder","q":"Describe the patterns of spread of bladder cancer.",
  "a": "<b>Direct extension:</b> en bloc (~60%), tentacle-like (~25%), lateral spread under normal mucosa (~10%). <b>Implantation</b> in wounds/denuded urothelium. <b>Lymphatic</b> (pelvic nodes): obturator 74%, external iliac 65%, paravesical 16%, presacral ~25%. <b>Vascular:</b> liver, lung, bone."},
 {"cat":"Bladder","q":"What is the most common presentation of bladder cancer?",
  "a": "<b>Painless hematuria — ~85%</b>. Second: bladder irritability — frequency, urgency, dysuria (usually with diffuse CIS or invasive cancer). Advanced: flank pain (ureteral obstruction), lower limb edema, pelvic mass, weight loss."},
 {"cat":"Bladder","q":"Give the TNM staging of bladder cancer (T).",
  "a": "<ul><li><b>Ta:</b> papillary, epithelium-confined</li><li><b>Tis:</b> flat carcinoma in situ</li><li><b>T1:</b> lamina propria invasion</li><li><b>T2a/b:</b> muscle-invasive (superficial/deep)</li><li><b>T3a/b:</b> perivesical fat (micro/macroscopic)</li><li><b>T4a:</b> pelvic viscera (prostate, rectum, uterus, vagina)</li><li><b>T4b:</b> pelvic sidewall/abdominal wall</li></ul>N1 ≤2 cm single node; N2 2–5 cm; N3 &gt;5 cm."},
 {"cat":"Bladder","q":"How is non-muscle-invasive bladder cancer (NMIBC) treated?",
  "a": "<b>TURBT</b> (resect whole lesion + sample underlying muscle); <b>intravesical therapy</b> — chemotherapy (mitomycin C) or <b>BCG</b> — reduces recurrence; photodynamic diagnosis with photosensitizers (hexa-aminolaevulinic acid) enhances tumor visibility; <b>radical cystectomy</b> for high-grade NMIBC failing TURBT + intravesical therapy."},
 {"cat":"Upper tract","q":"What are the risk factors for upper urinary tract urothelial tumors?",
  "a": "Male gender and increasing age; <b>smoking — the most important risk factor (2–3×)</b> (chemical carcinogens: aniline, benzidine, aromatic amines, azo dyes); cyclophosphamide; heavy caffeine; chronic inflammation/infection; occupational exposure. TCC frequency: bladder &gt; renal pelvis &gt; ureter (125 : 2.5 : 1)."},
 {"cat":"Upper tract","q":"What is the gold-standard treatment of upper tract urothelial tumors?",
  "a": "<b>Radical nephroureterectomy + bladder cuff excision</b> — remove kidney + entire ureter including orifice (multifocality + high ipsilateral recurrence after partial resection). Endoscopic resection/fulguration for: solitary kidney, bilateral disease, renal dysfunction, intercurrent illness, selected small low-grade lesions."},
 {"cat":"Renal","q":"List the benign renal tumors and the Bosniak classification.",
  "a": "Commonest benign: renal cysts, <b>oncocytoma</b>, <b>angiomyolipoma</b>, renal adenomas. <b>Bosniak I:</b> thin wall, water density, no septa/calcification/enhancement. II: thin septa and/or fine calcification. (III/IV: more complex — suspicious/malignant.)"},
 {"cat":"Renal","q":"Give the overview and risk factors of renal cell carcinoma.",
  "a": "RCC = <b>85% of primary malignant renal tumors</b>; 5th–6th decade; M:F 3:2; grossly common in the upper pole; microscopic: clear cell, papillary, chromophobe, collecting duct. Risk factors: smoking, obesity, genetic (chromosomes 3 &amp; 7), <b>Von-Hippel-Lindau disease</b>, tuberous sclerosis, cystic disease on dialysis."},
 {"cat":"Renal","q":"Summarize the 2017 TNM staging of RCC.",
  "a": "<b>T1:</b> ≤7 cm, limited to kidney. <b>T2:</b> &gt;7 cm (≤10), limited to kidney. <b>T3:</b> into major veins or perinephric tissues, within Gerota fascia — T3a: renal vein/segmental branches, pelvicalyceal system, perirenal/sinus fat; T3b: IVC below diaphragm; T3c: IVC above diaphragm or caval wall invasion. <b>T4:</b> beyond Gerota fascia (incl. ipsilateral adrenal)."},
 {"cat":"Renal","q":"What is the clinical picture and treatment of RCC?",
  "a": "Classic triad: gross hematuria, loin pain, palpable mass (rare today — most are incidental). Also metastasis, secondary varicocele, paraneoplastic (Stauffer syndrome, anemia, erythrocytosis, amyloidosis, hypercalcemia). Treatment: localized → <b>radical nephrectomy</b>; metastatic → radiotherapy, chemotherapy, immunotherapy, hormonal therapy, surgery."},
 {"cat":"Testis","q":"Give the key facts of testicular tumors (epidemiology, aetiology, presentation).",
  "a": "Most common GU malignancy in males <b>15–35 years</b>; cure rate ~90%; more common on the right; more common in Caucasians. Aetiology: <b>cryptorchidism — commonest risk factor</b> (orchiopexy does not prevent cancer), orchitis/trauma, HIV, family history, CIS, atrophy. Presentation: painless scrotal lump; acute pain in 10% (hemorrhage); gynecomastia in 5% (functional metastasis)."},
 {"cat":"Testis","q":"Classify germ cell tumors of the testis.",
  "a": "<b>Seminoma (40%):</b> 70% confined to testis; radio- and chemo-sensitive; classic (80%), spermatocytic (best prognosis, &gt;50 y), anaplastic (worse). <b>Non-seminomatous (main 4):</b> yolk sac (most common in infancy; <b>AFP ↑ in 90%</b>), embryonal carcinoma (smallest, highly malignant), teratoma (bone/cartilage/intestinal tissue), <b>choriocarcinoma (worst prognosis; HCG ↑ in all)</b>. Non-germ cell: Sertoli/Leydig cell tumors."},
 {"cat":"Testis","q":"How are testicular tumors diagnosed and treated?",
  "a": "Diagnosis: scrotal duplex US, CT chest/abdomen/pelvis, PET. Treatment: <b>ipsilateral radical orchiectomy first</b> (also diagnostic), then radiotherapy, chemotherapy, retroperitoneal lymph node dissection as staged. pT1: limited to testis/epididymis, no vascular invasion; pT2: with vascular invasion or tunica vaginalis involvement."},
]

