trauma = [
 {"cat":"Overview","q":"What are the initial management principles of urological trauma?",
  "a": "~10% of ER injuries involve the GU system. Control hemorrhage/shock + resuscitation; IV lines; <b>examine the urethral meatus for blood BEFORE passing a urethral catheter in men</b>; detailed history (type/calibre of weapon in gunshot wounds); examine abdomen/genitalia for contusions or subcutaneous hematomas suggesting deep injury."},
 {"cat":"Renal","q":"Give the epidemiology and classification (grades) of renal injuries.",
  "a": "Renal injuries are the most common urinary system injuries; <b>blunt trauma 80–85%</b>; pathological kidneys (hydronephrosis, tumors) rupture more easily. Grades: <b>1 — contusion (most common); 2 — cortical laceration, small perirenal hematoma; 3 — deeper laceration; 4 — ... ; 5 — pedicle avulsion/shattered kidney</b>. The degree of hematuria does NOT correspond to injury severity."},
 {"cat":"Renal","q":"How are renal injuries staged and when is imaging indicated?",
  "a": "<b>CT is the gold standard</b> for staging — lacerations, extravasation, hematoma extent, nonviable tissue, associated organ injury. IVP if CT unavailable. Indications: any hematuria after trauma; flank stab/gunshot wounds even without hematuria; rapid deceleration (vascular injury may have NO hematuria). <b>Non-visualization on IVU:</b> pedicle avulsion, arterial thrombosis, severe contusion with vascular spasm, absent kidney."},
 {"cat":"Renal","q":"What are the complications of renal trauma?",
  "a": "Early: <b>hemorrhage</b> (most important — heavy retroperitoneal bleeding → collapse). Late: hypertension, hydronephrosis, arteriovenous fistula, calculus formation, pyelonephritis, renal atrophy. Follow-up: monitor BP for months; excretory urography at 3–6 months."},
 {"cat":"Renal","q":"How are renal injuries treated?",
  "a": "Minor blunt injuries (85%) — conservative: bed rest, hydration, observe. <b>Surgery</b> for: persistent retroperitoneal bleeding, urinary extravasation, nonviable parenchyma, renal pedicle injuries (&lt;5% of injuries). <b>Penetrating injuries are surgically explored</b> (exception: complete staging shows only minor parenchymal injury)."},
 {"cat":"Ureter","q":"When does ureteral injury occur and what is its pathogenesis?",
  "a": "Rare: difficult pelvic surgery (ligation/cut), endoscopic basket manipulation, gunshot wounds, rapid deceleration (avulsion from pelvis). <b>Partial division — early:</b> urinary extravasation, ileus/peritonitis, urinoma; <b>late:</b> ureterovaginal/ureterocutaneous fistula, fibrosis/stricture, hydronephrosis. <b>Bilateral complete ligation → anuria.</b> Prognosis excellent if diagnosed and corrected early."},
 {"cat":"Ureter","q":"How are ureteral injuries diagnosed?",
  "a": "Suspect with retroperitoneal stab/gunshot (mid-ureter most common site); fever, flank pain, ileus, watery discharge from wound/vagina (confirm by creatinine); IV indigo carmine appears blue in urine. Imaging: IVU (delayed excretion + hydronephrosis; extravasation), CTU/3D reconstruction, US (urinoma — best early post-op screen), radionuclide scan."},
 {"cat":"Ureter","q":"How are ureteral injuries treated?",
  "a": "Immediate re-exploration when recognized during surgery; delayed repair within 7–10 days if no infection/abscess; <b>percutaneous nephrostomy</b> if recognized late or complicated. Goals: complete debridement, tension-free spatulated anastomosis, watertight closure, ureteral stenting, drainage."},
 {"cat":"Bladder","q":"Describe the pathogenesis and clinical findings of bladder rupture.",
  "a": "~15% of pelvic fractures have bladder/urethral injury; <b>pelvic fracture accompanies bladder rupture in 90%</b>. Fracture fragments perforate → <b>extraperitoneal rupture</b>; direct blow to a full bladder → <b>intraperitoneal rupture</b>. Clinical: inability to void, gross hematuria, pelvic/lower abdominal pain, hemorrhagic shock (pelvic venous disruption), acute abdomen with intraperitoneal rupture, indistinct rectal landmarks from pelvic hematoma."},
 {"cat":"Bladder","q":"Describe the ascending cystogram technique and findings.",
  "a": "Fill bladder with 300 mL contrast → drain completely → take a second film. Demonstrates extraperitoneal extravasation (may not appear on filling film) and <b>intraperitoneal extravasation (free contrast in the abdomen)</b>. Complications: pelvic abscess (extraperitoneal rupture + infected hematoma), delayed peritonitis (intraperitoneal), partial incontinence (bladder neck injury)."},
 {"cat":"Bladder","q":"How is bladder rupture treated?",
  "a": "<b>Extraperitoneal:</b> urethral catheter drainage alone usually suffices (~10 days). <b>Intraperitoneal:</b> surgical repair via transperitoneal approach — close perforations, close peritoneum carefully, close bladder in layers with absorbable suture, evacuate all extravasated fluid; suprapubic cystostomy left in place; avoid entering the lateral pelvic hematoma. Prognosis excellent; catheter removed ~10 days."},
 {"cat":"Urethra","q":"What are the anatomic divisions of the urethra and how do they relate to injury?",
  "a": "<b>Posterior urethra</b> = prostatic + membranous portions — injured by <b>pelvic fractures</b> (membranous urethra sheared from the prostatic apex). <b>Anterior urethra</b> = bulbous + pendulous portions — injured by <b>straddle falls</b>. <b>Blood at the urethral meatus is the single most important sign of urethral injury</b>."},
 {"cat":"Urethra","q":"What are the dangers of passing a catheter in posterior urethral injury?",
  "a": "May infect the periprostatic/perivesical hematoma and convert an incomplete laceration into a complete one. Management: treat shock/hemorrhage; <b>avoid urethral catheterization</b>; <b>suprapubic cystostomy</b> for 3 months; incomplete laceration heals spontaneously (catheter removed 2–3 weeks after no extravasation on VCUG); delayed reconstruction after 3 months."},
 {"cat":"Urethra","q":"Compare primary repair vs delayed reconstruction for posterior urethral injury.",
  "a": "<b>Stricture:</b> ~50% (primary) vs ~5% (delayed). <b>Impotence:</b> 30–80% mean ~50% vs 30–35%. <b>Incontinence:</b> one-third vs &lt;5%. <b>Delayed reconstruction after suprapubic drainage dramatically reduces all three complications.</b>"},
 {"cat":"Urethra","q":"Describe anterior urethral injury — pathogenesis and complications.",
  "a": "Straddle injury or instrumentation; contusion (perineal hematoma, resolves) vs laceration (urine extravasation limited by <b>Colles' fascia</b> — extends into scrotum, penile shaft, abdominal wall → sepsis). Complications: bleeding (corpus spongiosum; local pressure), infection/sepsis (debridement + drainage), <b>stricture</b> (common; often mild). Management: suprapubic cystostomy; voiding study at 7 days (minor) or 2–3 weeks (extensive); extensive extravasation → immediate repair."},
]

